ALTER TABLE "discipline_outcomes" DROP CONSTRAINT "discipline_shape";--> statement-breakpoint
ALTER TABLE "discipline_outcomes" ADD CONSTRAINT "discipline_shape" CHECK ("discipline_outcomes"."expected_revision">=0 and octet_length("discipline_outcomes"."fingerprint")=32 and octet_length("discipline_outcomes"."reason") between 1 and 1024 and btrim("discipline_outcomes"."reason")<>''
    and (("discipline_outcomes"."action" in ('BLOCK','UNBLOCK') and "discipline_outcomes"."round_id" is null and "discipline_outcomes"."team_round_id" is null and "discipline_outcomes"."original_id" is null and "discipline_outcomes"."minutes" is null
      and ("discipline_outcomes"."action"='BLOCK' or "discipline_outcomes"."block_id" is not null))
      or ("discipline_outcomes"."action" in ('PENALISE','REVERSE') and "discipline_outcomes"."round_id" is not null and "discipline_outcomes"."team_round_id" is not null and "discipline_outcomes"."member_id" is null and "discipline_outcomes"."block_id" is null
        and (("discipline_outcomes"."action"='PENALISE' and "discipline_outcomes"."original_id" is null and "discipline_outcomes"."minutes" is not null and "discipline_outcomes"."minutes" between 1 and 300) or ("discipline_outcomes"."action"='REVERSE' and "discipline_outcomes"."original_id" is not null and "discipline_outcomes"."minutes" is null))))
    and (("discipline_outcomes"."outcome"='APPLIED' and "discipline_outcomes"."denial_reason" is null and ("discipline_outcomes"."action"<>'BLOCK' or "discipline_outcomes"."block_id" is not null))
      or ("discipline_outcomes"."outcome"='REJECTED' and "discipline_outcomes"."denial_reason" is not null and "discipline_outcomes"."denial_reason" in ('STALE_VERSION','ARENA_UNAVAILABLE','ROUND_UNAVAILABLE','ALREADY_BLOCKED','ALREADY_CLEARED','PENALTY_CAP','ALREADY_REVERSED'))));